const english=document.documentElement.lang==='en';
const captions=english?{all:'One Mac. Three destinations. Three routes.',personal:'Video service → personal VPN: TUN, proxy or WireGuard. Configure it separately.',work:'Work portal → selected network 10.20.0.0/16 → ocbar.',lan:'Home NAS 192.168.50.20 → direct over LAN.'}:{all:'Один Mac. Три назначения. Три пути.',personal:'Видеосервис → личный VPN: TUN, прокси или WireGuard. Настраивается отдельно.',work:'Рабочий портал → выбранная сеть 10.20.0.0/16 → ocbar.',lan:'Домашний NAS 192.168.50.20 → напрямую по LAN.'};
  document.querySelectorAll('[data-route]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-route]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));document.querySelector('#atlas svg').setAttribute('data-focus',button.dataset.route);document.querySelector('#route-caption').textContent=captions[button.dataset.route];}));
  const tabs=[...document.querySelectorAll('[role=tab]')];
  function setMode(button){const all=button.dataset.mode==='all';tabs.forEach(tab=>{tab.setAttribute('aria-selected',String(tab===button));tab.tabIndex=tab===button?0:-1;});const panel=document.querySelector('#compare-panel');panel.dataset.mode=button.dataset.mode;panel.setAttribute('aria-labelledby',button.id);document.querySelector('#internet-node').textContent=all?'Cisco AnyConnect':(english?'Personal VPN':'Личный VPN');document.querySelector('#work-node').textContent=all?'Cisco AnyConnect':'ocbar';document.querySelector('#mode-copy').textContent=english?(all?'In this example, the Cisco AnyConnect profile sends internet traffic through the VPN. LAN keeps a direct route.':'Work range 10.20.0.0/16 is selected. Personal VPN and LAN keep separate routes.'):all?'В этом примере профиль Cisco AnyConnect отправляет интернет-трафик через VPN. Для LAN сохранён прямой маршрут.':'Выбран рабочий диапазон 10.20.0.0/16. Личный VPN и LAN — отдельные маршруты.';}
  tabs.forEach(tab=>{tab.addEventListener('click',()=>setMode(tab));tab.addEventListener('keydown',event=>{if(['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?tabs[0]:event.key==='End'?tabs.at(-1):tabs[(tabs.indexOf(tab)+1)%tabs.length];setMode(next);next.focus();}});});
